-- Resources content for the Sourcework changes: projects without a file, many
-- uploads at once, the project list and delete confirmation, the source switcher, and
-- the reworked transcript workspace (CLAUDE.md, "Resources stay in step with the
-- code"). Content only; no schema.

select private.rc_release_guide(
  p_slug => 'sourcework-starting-a-project',
  p_tool_key => 'transcription',
  p_title => 'Starting a project and adding sources',
  p_summary => 'Name a project, then add recordings and PDFs now or later.',
  p_screen_keys => array['sourcework.projects'],
  p_sort_order => 5,
  p_version_note => 'Projects no longer need a file; many files upload at once',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A project is the workspace for one story. It starts with a name; sources, which are recordings and PDFs, are added to it now or later."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Create a project"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the Sourcework home page, select "},{"type":"text","text":"+ New project","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Type a title and, if you like, notes: what the project is about and who set it up."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Add sources now if you have them. Drag recordings or PDFs onto the box, or select "},{"type":"text","text":"Choose files","marks":[{"type":"bold"}]},{"type":"text","text":". Several at once is fine; each becomes its own source, titled from its file name. Rename any title before you upload."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Create project","marks":[{"type":"bold"}]},{"type":"text","text":", or "},{"type":"text","text":"Create project and upload","marks":[{"type":"bold"}]},{"type":"text","text":" with the number of files."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"While files upload"}]},{"type":"paragraph","content":[{"type":"text","text":"Files upload three at a time. One bar shows overall progress, with a line for each file in progress. A file that fails stays at the top with the reason and a "},{"type":"text","text":"Retry","marks":[{"type":"bold"}]},{"type":"text","text":", and the rest carry on. An upload is not resumable, so a retry starts that file over."}]},{"type":"paragraph","content":[{"type":"text","text":"Stop","marks":[{"type":"bold"}]},{"type":"text","text":" lets the files already uploading finish and leaves the rest waiting; "},{"type":"text","text":"Resume","marks":[{"type":"bold"}]},{"type":"text","text":" starts them again. Keep the page open until it finishes. When every file is uploaded you land on the project. If some failed, the project is still created, and you can open it and add the rest later."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"After the upload"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Processing continues in the background. A banner on the project explains what is still running, and the page updates on its own when it is done."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Audio and video get a transcript. A PDF's text is extracted automatically: a plain read of the file first, falling back to OCR only when that is not enough."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If processing fails, the project offers "},{"type":"text","text":"Retry transcription","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Retry text extraction","marks":[{"type":"bold"}]},{"type":"text","text":". The file itself is already safely uploaded."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The project list"}]},{"type":"paragraph","content":[{"type":"text","text":"The Projects tab lists the most recently active projects first, 25 to a page. The filters above it show how many projects each holds: "},{"type":"text","text":"All","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Started by me","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Needs attention","marks":[{"type":"bold"}]},{"type":"text","text":" (a source failed to upload or process), and "},{"type":"text","text":"No sources","marks":[{"type":"bold"}]},{"type":"text","text":". Each row shows its sources, its excerpts, who started it and its status. Select anywhere on a row to open the project."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Deleting a project"}]},{"type":"paragraph","content":[{"type":"text","text":"Only the person who started a project can delete it. The "},{"type":"text","text":"Danger zone","marks":[{"type":"bold"}]},{"type":"text","text":" at the bottom of the project page asks once more, and names what will happen: sources that only this project uses are removed with their transcripts and excerpts, and sources that another project also uses stay in the library. A long list shows five names and a count."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A project does not need a source. One without any shows "},{"type":"text","text":"No sources","marks":[{"type":"bold"}]},{"type":"text","text":" in the list, and opens with an "},{"type":"text","text":"Add the first source","marks":[{"type":"bold"}]},{"type":"text","text":" button."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Anything outside the accepted audio, video and PDF types is refused before the upload starts, with a message naming what is accepted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The file goes straight from your browser to storage. A long recording can take a few minutes to upload."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Once a source is uploaded, it can be used in more than one project with no re-upload. See Add another source to a project."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-reference-another-source',
  p_tool_key => 'transcription',
  p_title => 'Add another source to a project',
  p_summary => 'Use one interview or document in more than one story, and move between a project''s sources.',
  p_screen_keys => array['sourcework.project'],
  p_sort_order => 10,
  p_version_note => 'Source switcher and multi-file upload',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A project can draw on more than one recording or document. When the same interview matters to more than one story, add it to each project instead of uploading it again. Every project then shares one original and one transcript."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add a source"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the project and select "},{"type":"text","text":"+ Add source","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On "},{"type":"text","text":"Find existing","marks":[{"type":"bold"}]},{"type":"text","text":", search for the source by title and choose it. It is added right away, with no confirmation step."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On "},{"type":"text","text":"Upload new","marks":[{"type":"bold"}]},{"type":"text","text":", drag in recordings or PDFs that are not in Sourcework yet, or select "},{"type":"text","text":"Choose files","marks":[{"type":"bold"}]},{"type":"text","text":". A project with no sources opens on Upload."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Switch between sources"}]},{"type":"paragraph","content":[{"type":"text","text":"The box above the transcript names the source that is open. Select it to see every source in the project, and type to narrow the list, which helps when a project has many. The arrows on either side step to the previous and next source."}]},{"type":"paragraph","content":[{"type":"text","text":"The page address includes ?source=, so you can send a colleague a link straight to a source. "},{"type":"text","text":"All excerpts","marks":[{"type":"bold"}]},{"type":"text","text":" shows the excerpts from every source in the project, with a search box that covers the whole project."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An excerpt belongs to the source that was open when you made it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Retrying a failed transcription retries the open source, not the project's first one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"PDF documents are added the same way as audio. They open in the document viewer instead of the player."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-transcript-and-excerpts',
  p_tool_key => 'transcription',
  p_title => 'Working with the transcript and creating excerpts',
  p_summary => 'Find your way in a transcript, name speakers, and save a stretch of it as an excerpt.',
  p_screen_keys => array['sourcework.project', 'sourcework.source'],
  p_sort_order => 15,
  p_version_note => 'Find, speakers list, line menu, selection bar, excerpt marks',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The transcript is on the left and the project's excerpts for this source are on the right. Excerpts are short clips saved for reuse."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find your way"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find in this transcript","marks":[{"type":"bold"}]},{"type":"text","text":" looks for a word or phrase from two characters on. Matching words are highlighted. Select the arrows, or press Enter, to step through the matches."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The marks under the progress bar show where your excerpts are; select one to open it. With many excerpts the marks merge into a shaded strip, and darker means more excerpts there."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Speakers","marks":[{"type":"bold"}]},{"type":"text","text":" button names the speakers, with the first few names after it. It opens a list ordered by who spoke most. Type a name to rename a speaker, or select "},{"type":"text","text":"Hear an example","marks":[{"type":"bold"}]},{"type":"text","text":". From seven speakers a find box and an "},{"type":"text","text":"Unnamed only","marks":[{"type":"bold"}]},{"type":"text","text":" switch appear."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If the transcript split one person into two voices, select "},{"type":"text","text":"Merge…","marks":[{"type":"bold"}]},{"type":"text","text":" on the extra speaker and choose who it really was. All of its lines move to that speaker."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a line"}]},{"type":"paragraph","content":[{"type":"text","text":"Select the ⋮ at the end of any line for "},{"type":"text","text":"Edit text","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Change speaker…","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Merge with the next line","marks":[{"type":"bold"}]},{"type":"text","text":". Double-clicking the text, or pressing E on the current line, also starts an edit."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Create an excerpt"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Drag to select the stretch of text you want."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A bar opens at the bottom of the transcript with a title already filled in from the first words, and the time range beside it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Change the title if you like, then press Enter or select "},{"type":"text","text":"Save excerpt","marks":[{"type":"bold"}]},{"type":"text","text":". "},{"type":"text","text":"Preview","marks":[{"type":"bold"}]},{"type":"text","text":" plays the exact range; Esc cancels."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Working with excerpts"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The panel lists this source's excerpts. "},{"type":"text","text":"In order","marks":[{"type":"bold"}]},{"type":"text","text":" follows the recording and "},{"type":"text","text":"Newest","marks":[{"type":"bold"}]},{"type":"text","text":" puts the latest first. From nine excerpts a filter box appears, and twenty show at a time with "},{"type":"text","text":"Show more","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trim","marks":[{"type":"bold"}]},{"type":"text","text":" opens buttons to nudge the start or end of a clip by a small step or a larger one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Export WAV","marks":[{"type":"bold"}]},{"type":"text","text":" renders the clip to its own audio file; "},{"type":"text","text":"Download","marks":[{"type":"bold"}]},{"type":"text","text":" appears when it is ready."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Export excerpts (zip)","marks":[{"type":"bold"}]},{"type":"text","text":" in the project's header exports every excerpt in the project at once."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select a card's title to rename it. "},{"type":"text","text":"Delete","marks":[{"type":"bold"}]},{"type":"text","text":" asks you to confirm."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A PDF source works the same way, but you select a stretch of the extracted text instead of a time range."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trimming a clip after it has been exported makes that export stale. Re-export before you rely on the download."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Line menus and the speaker list work on a tablet or phone too: nothing waits on hovering."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-search',
  p_tool_key => 'transcription',
  p_title => 'Searching across projects and sources',
  p_summary => 'Find a transcript, excerpt or interview by what was said.',
  p_screen_keys => array['sourcework.projects', 'sourcework.project', 'sourcework.source'],
  p_sort_order => 25,
  p_version_note => 'Results grouped by project and filtered by kind',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The search box on the Sourcework home page searches every project, source, transcript, document and excerpt you can open. Type what you are looking for and press Enter."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How results work"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Results are grouped by project, so several hits from one interview read as one project. The first three show, and "},{"type":"text","text":"Show more","marks":[{"type":"bold"}]},{"type":"text","text":" opens the rest. The words you searched for are highlighted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The chips above the results narrow them by kind: "},{"type":"text","text":"Excerpts","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"In transcripts","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"In documents","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Projects","marks":[{"type":"bold"}]},{"type":"text","text":", each with its count."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Clear search","marks":[{"type":"bold"}]},{"type":"text","text":" to return to the project list."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Searching inside a project"}]},{"type":"paragraph","content":[{"type":"text","text":"All excerpts","marks":[{"type":"bold"}]},{"type":"text","text":", in a project, has a search box that covers only that project. To find a word inside one transcript, use "},{"type":"text","text":"Find in this transcript","marks":[{"type":"bold"}]},{"type":"text","text":" above it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The line under the search box says what kind of search is running. Administrators also see whether topic search, which finds a passage by what it is about and not only its exact words, is switched on."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Topic search depends on an optional service. When it is off, keyword search still finds everything; it just will not catch a paraphrase."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-08-sourcework-projects-and-uploads',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-08',
  p_title => 'Start a project without a file, and upload many at once',
  p_guide_slugs => array['sourcework-starting-a-project', 'sourcework-reference-another-source'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"You can now start a project without a file: give it a name and add sources when you have them. When you do have files, drag in as many as you like. They upload three at a time with a progress bar, failures wait at the top with a Retry, and the project is created either way. The Projects list now pages, with filters for the ones you started, the ones that need attention and the ones with no sources, and deleting a project says which sources go and which stay in the library."}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-08-sourcework-workspace',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-08',
  p_title => 'A taller transcript, find, and a speaker list that scales',
  p_guide_slugs => array['sourcework-transcript-and-excerpts', 'sourcework-search'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The transcript now fills the screen height beside the excerpt panel. Every line has a ⋮ menu that works on touch screens, the speaker list is one button that stays usable with a dozen voices and can merge a split speaker, and you can find a word in a transcript. Selecting words opens a bar with a suggested title, so saving an excerpt is one keypress. Marks under the progress bar show where your excerpts are, a project's sources are chosen from a searchable box, and search results are grouped by project and can be filtered by kind."}]}]}$body$
);
